// ============================================================
// PREPARE CONTACTS FOR SCORING LOOP
// ============================================================
// Extracts the contact list from the HubSpot search response
// and passes each contact as a separate item into
// SplitInBatches for individual processing.
//
// Note on pagination:
// HubSpot returns up to 100 contacts per request.
// For portals with >100 contacts, a pagination loop
// would be needed. For the current scale this is sufficient.
// The nightly scorer v1.1 can add pagination when needed.
// ============================================================

const response = $input.first().json;
const contacts = response.results || [];

if (contacts.length === 0) {
  console.log('[SCORER] No contacts found with email. Exiting.');
  return [];
}

console.log(`[SCORER] Starting nightly run. Contacts to score: ${contacts.length}`);
console.log(`[SCORER] Run started at: ${new Date().toISOString()}`);

// Pass each contact as its own item into the batch loop
return contacts.map(contact => ({
  json: {
    contactId:  contact.id,
    properties: contact.properties || {}
  }
}));

// ============================================================
// CALCULATE ENGAGEMENT SCORE
// ============================================================
// Reads HubSpot native fields (read-only — we only READ here)
// and produces canonical field values to write back.
//
// PRIMARY SIGNAL:
//   hs_email_sends_since_last_engagement
//   The number of emails sent since the contact last opened
//   or clicked anything. Increments on each send, resets
//   to 0 when they engage. Best single decay indicator.
//
// SECONDARY SIGNALS:
//   Historical opens/clicks add a depth bonus — contacts
//   who engaged a lot historically get partial credit even
//   if they've gone quiet recently.
//
// DECAY THRESHOLDS (configurable):
//   AT_RISK:  3  sends without engagement
//   COLD:     5  sends without engagement
//   DORMANT:  8  sends without engagement
// ============================================================

// ---- Configurable thresholds — adjust per client ----
const THRESHOLDS = {
  AT_RISK: 3,
  COLD:    5,
  DORMANT: 8
};

// ---- Score weight configuration ----
const WEIGHTS = {
  SENDS_PENALTY_PER:  12,  // deduct per send-since-engagement
  MAX_SENDS_PENALTY:  80,  // cap total sends penalty
  OPENS_BONUS_PER:     3,  // add per historical open
  MAX_OPENS_BONUS:    25,  // cap total opens bonus
  CLICKS_BONUS_PER:    5,  // add per historical click
  MAX_CLICKS_BONUS:   25,  // cap total clicks bonus
  OPTOUT_PENALTY:     50   // hard deduction for opted-out
};

// ---- Helper: days between a date string and now ----
function daysSince(dateStr) {
  if (!dateStr) return null;
  const diffMs = Date.now() - new Date(dateStr).getTime();
  return Math.max(0, Math.floor(diffMs / 86400000));
}

// ---- Helper: classify status from sends-since-engagement ----
function classifyStatus(sendsSinceLast, optedOut) {
  if (optedOut)                              return 'Opted Out';
  if (sendsSinceLast >= THRESHOLDS.DORMANT)  return 'Dormant';
  if (sendsSinceLast >= THRESHOLDS.COLD)     return 'Cold';
  if (sendsSinceLast >= THRESHOLDS.AT_RISK)  return 'At Risk';
  return 'Active';
}

// ---- Helper: calculate 0-100 engagement score ----
function calculateScore(sendsSinceLast, opens, clicks, optedOut) {
  let score = 100;

  // Primary decay: each send without engagement is penalized
  score -= Math.min(sendsSinceLast * WEIGHTS.SENDS_PENALTY_PER, WEIGHTS.MAX_SENDS_PENALTY);

  // Historical depth: contacts who engaged a lot get partial credit
  score += Math.min(opens  * WEIGHTS.OPENS_BONUS_PER,  WEIGHTS.MAX_OPENS_BONUS);
  score += Math.min(clicks * WEIGHTS.CLICKS_BONUS_PER, WEIGHTS.MAX_CLICKS_BONUS);

  // Opted out is a hard negative signal
  if (optedOut) score -= WEIGHTS.OPTOUT_PENALTY;

  return Math.min(100, Math.max(0, Math.round(score)));
}

// ---- Process the current contact ----
const { contactId, properties: p } = $input.first().json;

const sendsSinceLast = parseInt(p.hs_email_sends_since_last_engagement || '0', 10);
const totalOpens     = parseInt(p.hs_email_open  || '0', 10);
const totalClicks    = parseInt(p.hs_email_click || '0', 10);
const optedOut       = p.hs_email_optout === 'true';

// Most recent engagement date — prefer click over open
const lastEngagementDate = [
  p.hs_email_last_click_date,
  p.hs_email_last_open_date
].filter(Boolean).sort().reverse()[0] || null;

const daysSinceEngagement = daysSince(lastEngagementDate);

const engagementScore  = calculateScore(sendsSinceLast, totalOpens, totalClicks, optedOut);
const engagementStatus = classifyStatus(sendsSinceLast, optedOut);

const contactName = [p.firstname, p.lastname].filter(Boolean).join(' ')
  || p.email
  || `Contact ${contactId}`;

console.log(`[SCORER] ${contactName} → ${engagementStatus} (score: ${engagementScore}, sends: ${sendsSinceLast})`);

return [{
  json: {
    contactId,
    contactName,
    engagementScore,
    engagementStatus,
    daysSinceEngagement,
    // The canonical fields we will write back to HubSpot
    canonicalFields: {
      canon_engagement_score:           String(engagementScore),
      canon_engagement_status:          engagementStatus,
      canon_days_since_engagement:      String(daysSinceEngagement ?? ''),
      canon_engagement_last_calculated: new Date().toISOString()
    }
  }
}];

// Log result for this contact and pass back to loop
const calc = $('Calculate Score').first().json;
console.log(`[SCORER] ✓ Written: ${calc.contactName} → ${calc.engagementStatus} (${calc.engagementScore})`);
return [{ json: { done: true, contactId: calc.contactId } }];

// ============================================================
// RUN COMPLETE SUMMARY
// ============================================================
// Pulls all processed items from the loop and assembles
// a summary of the nightly run for Slack notification.
// ============================================================

// Count how many items were processed by reading the
// total from the SplitInBatches context
const allCalcItems = $('Calculate Score').all();

const statusCounts = allCalcItems.reduce((acc, item) => {
  const status = item.json.engagementStatus || 'Unknown';
  acc[status] = (acc[status] || 0) + 1;
  return acc;
}, {});

const totalProcessed = allCalcItems.length;
const avgScore = totalProcessed > 0
  ? Math.round(allCalcItems.reduce((sum, i) => sum + (i.json.engagementScore || 0), 0) / totalProcessed)
  : 0;

const flaggedCount = allCalcItems.filter(
  i => !['Active'].includes(i.json.engagementStatus)
).length;

console.log(`[SCORER] ✅ Nightly run complete.`);
console.log(`[SCORER] Total processed: ${totalProcessed}`);
console.log(`[SCORER] Avg score: ${avgScore}`);
console.log(`[SCORER] Flagged: ${flaggedCount}`);
console.log(`[SCORER] Status breakdown:`, JSON.stringify(statusCounts));

// Build Slack summary line
const statusLine = Object.entries(statusCounts)
  .filter(([, count]) => count > 0)
  .map(([status, count]) => `${count} ${status}`)
  .join(' · ');

const slackMessage = flaggedCount === 0
  ? `✅ *Nightly Engagement Scorer — Complete*\n${totalProcessed} contacts scored. All Active. Avg score: *${avgScore}/100*.`
  : `⏰ *Nightly Engagement Scorer — Complete*\n${totalProcessed} contacts scored · Avg score: *${avgScore}/100*\n${statusLine}\n\n${flaggedCount} contact${flaggedCount === 1 ? '' : 's'} flagged. Run /engagement-check for full details.`;

return [{
  json: {
    totalProcessed,
    avgScore,
    flaggedCount,
    statusCounts,
    slackMessage,
    completedAt: new Date().toISOString()
  }
}];

const error = $input.first().json;
console.error('[SCORER ERROR]', JSON.stringify({
  workflow:  'Nightly Engagement Scorer v1.0',
  error:     error.message || 'Unknown error',
  node:      error.node?.name || 'Unknown',
  timestamp: new Date().toISOString()
}));
return [{ json: { logged: true } }];
